command:
const actorID = token?.actor?.id || game.user?.character?.id;
if (!actorID) {
  ui.notifications.warn("No selected token or character assigned to you")
  return;
}


const thralls = canvas.tokens.placeables.filter((tok) => 
  tok?.document?.actor?.flags?.["pf2e-summons-assistant"]?.summoner?.id === actorID &&
    tok?.document?.actor?.flags?.pf2e?.rollOptions?.all?.["self:trait:thrall"]
)

const proceed = await foundry.applications.api.DialogV2.confirm({
  content:`Delete all thralls (${thralls?.length}) for ${game.actors?.get(actorID)?.name}`,
  rejectClose: false,
  modal: true
});
if ( proceed )  {
    canvas.scene.deleteEmbeddedDocuments("Token", thralls?.map(t => t?.id))
  ui.notifications.info("Thralls deleted")
}
